-- Mindtrip — Подорожі
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mindtrip.ai' OR LOWER(`name`) = LOWER('Mindtrip'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Mindtrip', NULL, 'https://mindtrip.ai', NULL, NULL, 'AI-помічник для подорожей, який запам''ятовує ваш стиль, підбирає перельоти, житло й ресторани, стежить за цінами та збирає маршрут і бронювання в одному місці.', 'An AI travel assistant that remembers your style, finds flights, stays and restaurants, watches prices and keeps your itinerary and bookings in one place.', 'Mindtrip — персональний AI-помічник для планування й бронювання подорожей. Він запам''ятовує ваші вподобання, тож не треба щоразу пояснювати, що вам подобається, і підбирає перельоти, житло, ресторани, екскурсії та події відповідно до ваших пріоритетів. Помічник попереджає про зниження цін, зміни рейсів і вільні столики, а маршрут, ідеї та бронювання зберігаються в одній поїздці. Бронювати можна прямо на платформі. Працює у вебі та в застосунку для iOS; ціни сервіс на сайті не публікує.', 'Mindtrip is a personal AI assistant for planning and booking trips. It remembers your preferences, so you do not have to explain your taste every time, and finds flights, stays, restaurants, experiences and events that match your priorities. It alerts you to price drops, flight changes and restaurant availability, and keeps your itinerary, ideas and bookings together in one trip. You can book directly on the platform. It works on the web and in an iOS app; pricing is not published on the website.', 'Запам''ятовує ваш стиль подорожей
Підбір перельотів, житла й ресторанів
Сповіщення про ціни та зміни рейсів
Маршрут і бронювання в одному місці', 'Remembers your travel style
Finds flights, stays and restaurants
Price-drop and flight-change alerts
Itinerary and bookings in one place', 'Мандрівники, які хочуть спланувати поїздку швидко й з урахуванням своїх уподобань.', 'Travellers who want to plan trips quickly and around their own preferences.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
