-- Layla — Подорожі
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'layla.ai' OR LOWER(`name`) = LOWER('Layla'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Layla', NULL, 'https://layla.ai', NULL, NULL, 'AI-планувальник подорожей: створює маршрут за кілька хвилин, надихає ідеями, допомагає з автоподорожжю чи поїздкою в останній момент; за потреби — допомога експертів.', 'An AI trip planner: it builds an itinerary in minutes, offers inspiration and helps with road trips or last-minute getaways, with travel experts on hand when needed.', 'Layla допомагає спланувати подорож у розмові з AI. Можна попросити створити новий маршрут, підказати, куди поїхати, зібрати автоподорож або спланувати поїздку в останній момент — Layla запропонує план по днях з місцями, активностями й житлом, а доопрацювати його допоможуть експерти з подорожей. Сервісом уже складено понад 2 млн поїздок. Ціни на сайті не опубліковано.', 'Layla helps you plan a trip in conversation with AI. You can ask it to build a new itinerary, suggest where to go, plan a road trip or organise a last-minute getaway — Layla proposes a day-by-day plan with places, activities and stays, and travel experts can help polish it. More than 2 million trips have been planned with it. Pricing is not published on the website.', 'Маршрут по днях за кілька хвилин
Ідеї, куди поїхати
Автоподорожі та поїздки в останній момент
Допомога експертів з подорожей', 'Day-by-day itinerary in minutes
Inspiration on where to go
Road trips and last-minute trips
Help from travel experts', 'Мандрівники, які не люблять довго планувати поїздки самостійно.', 'Travellers who do not like spending hours planning trips themselves.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
