INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wonderplan', NULL, 'https://wonderplan.ai', NULL, NULL, 'Безкоштовний AI-планувальник подорожей: створює персональний маршрут під ваші вподобання, рекомендує житло й дає завантажити план у PDF.', 'A free AI trip planner: it creates a personal itinerary around your preferences, recommends places to stay and lets you download the plan as a PDF.', 'Wonderplan складає персональний маршрут подорожі за вашими вподобаннями — напрямком, датами, бюджетом та інтересами. Готовий план можна змінювати: переставляти, додавати й видаляти місця; AI рекомендує житло, а всі поїздки зберігаються в особистому кабінеті. Маршрут можна завантажити у PDF, щоб мати його під рукою без інтернету. Сервіс зараз безкоштовний.', 'Wonderplan builds a personal travel itinerary around your preferences — destination, dates, budget and interests. You can edit the finished plan by reordering, adding and removing places; AI recommends accommodation, and all your trips are kept in a personal dashboard. The itinerary can be downloaded as a PDF so you have it offline. The service is currently free.', 'Персональний маршрут за вподобаннями
Редагування маршруту
Рекомендації житла
Завантаження в PDF', 'Personal itinerary based on preferences
Itinerary editing
Accommodation recommendations
PDF download', 'Мандрівники, які хочуть безкоштовно отримати готовий план поїздки.', 'Travellers who want a ready trip plan for free.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
