SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'phia.com' OR LOWER(`name`) = LOWER('Phia'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Phia', NULL, 'https://phia.com', NULL, NULL, 'AI-агент для покупок одягу й аксесуарів: шукає речі за описом на 220 000+ сайтах і знаходить дешевші варіанти товару, який ви переглядаєте.', 'An AI shopping agent for fashion: it searches 220,000+ sites from your description and finds cheaper alternatives to the item you are viewing.', 'Phia допомагає не переплачувати за одяг і аксесуари. Опишіть, що шукаєте, — наприклад, «шкіряна куртка до $300» чи «сумка для офісу», — і AI-агент знайде відповідні речі на понад 220 000 сайтів. Розширення для Chrome на сторінці будь-якого товару показує дешевші альтернативи та найнижчу ціну, а за покупки можна отримувати подарункові картки. Ціни сервіс на сайті не публікує.', 'Phia helps you avoid overpaying for clothes and accessories. Describe what you are looking for — for example, ''a leather jacket under $300'' or ''a tote for the office'' — and the AI agent finds matching items across more than 220,000 sites. The Chrome extension shows cheaper alternatives and the lowest price on any product page, and you can earn gift cards for purchases. Pricing is not published on the website.', 'Пошук речей за описом на 220 000+ сайтах
Дешевші альтернативи на сторінці товару
Розширення для Chrome
Подарункові картки за покупки', 'Search 220,000+ sites by description
Cheaper alternatives on product pages
Chrome extension
Gift cards for purchases', 'Покупці одягу й аксесуарів онлайн, які хочуть знайти найкращу ціну.', 'Online fashion shoppers who want the best price.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
