SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'daydream.ing' OR LOWER(`name`) = LOWER('Daydream'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Daydream', NULL, 'https://daydream.ing', NULL, NULL, 'Персональний AI-агент моди: шукайте одяг у 10 000+ магазинах і брендах через один чат, з урахуванням вашого профілю стилю.', 'A personal AI fashion agent: shop across 10,000+ stores and brands through one chat, tailored to your style profile.', 'Daydream дає змогу купувати одяг, просто розповідаючи в чаті, що вам потрібно. Ви створюєте профіль стилю, а AI-агент шукає підхожі речі в понад 10 000 магазинах і брендах моди та показує їх в одному місці, тож не треба відкривати десятки сайтів. Сервіс доступний у вебі та в застосунку. Ціни на сайті не опубліковано.', 'Daydream lets you shop for clothes simply by describing what you need in a chat. You build a style profile, and the AI agent searches more than 10,000 fashion stores and brands and shows matching items in one place, so you do not need to open dozens of sites. It is available on the web and as an app. Pricing is not published on the website.', 'Покупки одягу через чат
10 000+ магазинів і брендів
Профіль стилю
Веб і застосунок', 'Shop for clothes through chat
