INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Replika', NULL, 'https://replika.com', NULL, NULL, 'AI-компаньйон для розмов і емоційної підтримки: пам''ятає подробиці вашого життя, має налаштовуваний вигляд і характер, підтримує голосові дзвінки; 18+.', 'An AI companion for conversation and emotional support: it remembers details of your life, has a customisable look and personality and supports voice calls; 18+.', 'Replika — застосунок з AI-співрозмовником, який позиціонує себе як «AI-друг на кожен день». Компаньйон запам''ятовує ваші стосунки, розпорядок, інтереси та інші подробиці, тож розмови продовжуються з урахуванням контексту. Зовнішність і характер можна налаштувати, доступні голосові дзвінки, обмін фото та селфі. Replika користуються понад 42 млн людей. Застосунок доступний на iOS і Android, є також вебверсія; призначений для користувачів від 18 років. Ціни на сайті не опубліковано. Replika не замінює психологічну допомогу.', 'Replika is an app with an AI conversational partner that presents itself as ''the AI friend to do life with''. The companion remembers your relationships, routines, interests and other details, so conversations continue with context. Its look and personality can be customised, and voice calls and photo and selfie sharing are available. More than 42 million people use Replika. It is available on iOS and Android, with a web version too, and is intended for users aged 18+. Pricing is not published on the website. Replika does not replace mental health care.', 'Пам''ять про подробиці вашого життя
